// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime) public {
        // Ensure warpTime is in a reasonable range
        vm.assume(warpTime > 1 && warpTime < type(uint40).max);

        // Warp to a specific timestamp
        vm.warp(warpTime);

        // First call to set pastBlockTime
        vm.deal(address(this), 10 ether);
        (bool success1,) = address(c).call{value: 10 ether}("");
        assertTrue(success1, "First call should succeed");

        // Now warp to exactly the same timestamp (equal to pastBlockTime)
        vm.warp(warpTime);

        // Second call with same timestamp
        vm.deal(address(this), 10 ether);
        (bool success2,) = address(c).call{value: 10 ether}("");

        // The reference C should revert because block.timestamp == pastBlockTime is not allowed
        // The mutant M would succeed because it allows >= instead of >
        // So success2 must be false for the reference
        assertTrue(!success2, "Reference should revert on equal timestamp");
    }
}

